CREATE TABLE `products` (
  `product_id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL,
  `product_name` varchar(150) NOT NULL,
  `description` text,
  `country_id` int DEFAULT NULL,
  `maker_id` int DEFAULT NULL,
  `price` int DEFAULT NULL,
  `vintage` smallint DEFAULT NULL,
  `abv` decimal(4,1) DEFAULT NULL,
  `aroma_score` tinyint DEFAULT NULL,
  `taste_score` tinyint DEFAULT NULL,
  `sour_score` tinyint DEFAULT NULL,
  `richness_score` tinyint DEFAULT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`product_id`),
  KEY `country_id` (`country_id`),
  KEY `maker_id` (`maker_id`),
  KEY `idx_products_category` (`category_id`),
  KEY `idx_products_name` (`product_name`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`),
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`country_id`) REFERENCES `countries` (`country_id`),
  CONSTRAINT `products_ibfk_3` FOREIGN KEY (`maker_id`) REFERENCES `makers` (`maker_id`),
  CONSTRAINT `products_chk_1` CHECK ((`aroma_score` between 1 and 5)),
  CONSTRAINT `products_chk_2` CHECK ((`taste_score` between 1 and 5)),
  CONSTRAINT `products_chk_3` CHECK ((`sour_score` between 1 and 5)),
  CONSTRAINT `products_chk_4` CHECK ((`richness_score` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=401 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
